using System;using System.Reflection;using System.Collections.Generic;using System.Linq;using UnityEditor;
public static class ProductionViewport {static EditorWindow view;static object group;static int builtin,oldIndex;static List<int> added=new List<int>();static BindingFlags flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;
 public static void SetSize(int w,int h){if(!view)view=EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView"));var asm=typeof(Editor).Assembly;var sizes=asm.GetType("UnityEditor.GameViewSizes");var instance=typeof(ScriptableSingleton<>).MakeGenericType(sizes).GetProperty("instance",BindingFlags.Public|BindingFlags.Static).GetValue(null);var groupType=asm.GetType("UnityEditor.GameViewSizeGroupType");group=sizes.GetMethod("GetGroup",flags).Invoke(instance,new[]{sizes.GetProperty("currentGroupType",flags).GetValue(instance)});builtin=(int)group.GetType().GetMethod("GetBuiltinCount",flags).Invoke(group,null);var sizeType=asm.GetType("UnityEditor.GameViewSize");var enumType=asm.GetType("UnityEditor.GameViewSizeType");var size=Activator.CreateInstance(sizeType,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance,null,new object[]{Enum.Parse(enumType,"FixedResolution"),w,h,"HUD isolated QA "+w+"x"+h},null);group.GetType().GetMethod("AddCustomSize",flags).Invoke(group,new[]{size});int index=(int)group.GetType().GetMethod("GetTotalCount",flags).Invoke(group,null)-1;added.Add(index-builtin);view.GetType().GetMethod("SizeSelectionCallback",flags).Invoke(view,new object[]{index,null});view.Repaint();}
 public static void Cleanup(){if(group!=null)foreach(int index in added.OrderByDescending(x=>x))group.GetType().GetMethod("RemoveCustomSize",flags).Invoke(group,new object[]{index+builtin});added.Clear();if(view)view.GetType().GetProperty("selectedSizeIndex",flags).SetValue(view,oldIndex);}
}
